import ast

def _compatible(old, new):
    if type(old) is not type(new):
        return False
    if _descriptor(old) != _descriptor(new):
        return False
    oa, na = old.args, new.args
    if oa.vararg is not None and na.vararg is None:
        return False
    if oa.kwarg is not None and na.kwarg is None:
        return False
    op = oa.posonlyargs + oa.args
    np = na.posonlyargs + na.args
    if len(np) < len(op):
        return False
    nposonly = len(na.posonlyargs)
    for i in range(len(op)):
        if i >= len(op) - len(oa.defaults):
            if i < len(np) - len(na.defaults):
                return False
        if i >= len(oa.posonlyargs):
            if i < nposonly or np[i].arg != op[i].arg:
                return False
    old_required_kwonly = {
        arg.arg for arg, default in zip(oa.kwonlyargs, oa.kw_defaults)
        if default is None
    }
    extra_start = len(op)
    extra_end = len(np) - len(na.defaults)
    for i in range(extra_start, extra_end):
        if np[i].arg not in old_required_kwonly or i < nposonly:
            return False
    old_required_names = {
        a.arg for a in op[len(op) - len(oa.defaults):]
    } | old_required_kwonly
    for arg, default in zip(na.kwonlyargs, na.kw_defaults):
        if default is None and arg.arg not in old_required_names:
            return False
    new_named = {a.arg for a in na.args} | {a.arg for a in na.kwonlyargs}
    for arg in oa.kwonlyargs:
        if arg.arg not in new_named and na.kwarg is None:
            return False
    return True
